from __future__ import annotations

import argparse
import base64
import gzip
import json
import os
import re
import sys
import time
from pathlib import Path

# --------------------------------------------------------------------------
# Embedded data payloads (injected at build; see repo colab/ README note).
# transcripts: 5284 lines "utt_id\\tOlChiki", splits: train/dev/eval id lists.
# --------------------------------------------------------------------------
TRANSCRIPTS_GZ_B64 = ""
SPLITS_GZ_B64 = ""

QUIPUS_REPO = "hyperneuronAILabs/quipus-0.6-speechv2"
SNAC_REPO = "hubertsiuzdak/snac_24khz"
TEACHER_SR = 24000
TRAIN_SR = 22050
FRAME_LAYER_PATTERN = [0, 1, 2, 2, 1, 2, 2]
TOKEN_RE = re.compile(r"<snac_l(\d+)_c(\d+)>")

VALIDATE_CASES = [
    ("johaar", "ᱡᱚᱦᱟᱨ"),
    ("mt-question", "ᱪᱮᱫ ᱱᱚᱣᱟ ᱫᱤᱱ ᱱᱟᱯᱟᱭ ᱠᱟᱱᱟ?"),
    ("lesson-line", "ᱟᱞᱮ ᱟᱥᱲᱟ ᱥᱮᱱᱚᱜ ᱠᱟᱱᱟ"),
]


def W(args, *parts) -> Path:
    return Path(args.workdir, *parts)


def decode_payload(b64: str) -> str:
    return gzip.decompress(base64.b64decode(b64)).decode("utf-8")


def load_transcripts() -> list[tuple[str, str]]:
    rows = []
    for line in decode_payload(TRANSCRIPTS_GZ_B64).splitlines():
        if "\t" in line:
            uid, txt = line.split("\t", 1)
            rows.append((uid.strip(), txt.strip()))
    return rows


def load_splits() -> dict:
    return json.loads(decode_payload(SPLITS_GZ_B64))


def normalize(text: str) -> str:
    return " ".join(text.split()).replace("ᱽ", "")


def get_token() -> str:
    tok = os.environ.get("HF_TOKEN", "").strip()
    if tok:
        return tok
    try:
        from getpass import getpass
        tok = getpass("HF_TOKEN (huggingface.co/settings/tokens): ").strip()
    except Exception:
        tok = ""
    if not tok:
        sys.exit("HF_TOKEN missing — set env HF_TOKEN and retry.")
    return tok


# --------------------------------------------------------------------------
# stage: setup
# --------------------------------------------------------------------------
def stage_setup(args) -> int:
    import torch

    print(f"[setup] workdir={args.workdir} cuda={torch.cuda.is_available()}",
          end="")
    if torch.cuda.is_available():
        print(f" ({torch.cuda.get_device_name(0)}, "
              f"{torch.cuda.get_device_properties(0).total_memory / 1e9:.1f}GB)")
    else:
        print(" — WARNING: no GPU, teacher synthesis will be very slow")
    import shutil
    free_gb = shutil.disk_usage(args.workdir if Path(args.workdir).exists()
                                else "/content").free / 1e9
    print(f"[setup] disk free ~{free_gb:.1f}GB (need ~5GB: 1.2 model + "
          "~1.5 teacher + checkpoints)")
    mods = {}
    for m in ["transformers", "huggingface_hub", "snac", "soundfile",
              "librosa", "TTS", "sherpa_onnx", "onnx", "tensorboard"]:
        try:
            mod = __import__(m)
            mods[m] = getattr(mod, "__version__", "ok")
        except Exception as e:
            mods[m] = f"MISSING ({type(e).__name__})"
    for m, v in mods.items():
        print(f"[setup] {m}: {v}")
    try:
        import transformers
        if transformers.__version__ != "4.53.3":
            print(f"[setup] WARNING: want transformers==4.53.3, have "
                  f"{transformers.__version__} (coqui needs both "
                  "is_torchcodec_available and isin_mps_friendly)")
        else:
            print("[setup] transformer pin OK (4.53.3)")
    except ImportError:
        print("[setup] transformers MISSING — run the pip install cell")
    tok = os.environ.get("HF_TOKEN", "")
    print(f"[setup] HF_TOKEN {'set' if tok else 'NOT set (export it before download)'}")
    print("[setup] transcripts:", len(load_transcripts()), "| splits:",
          {k: len(v) for k, v in load_splits().items()})
    return 0


# --------------------------------------------------------------------------
# stage: download
# --------------------------------------------------------------------------
def stage_download(args) -> int:
    get_token()  # fail fast with clear message
    from huggingface_hub import snapshot_download

    dest = W(args, "quipus_model")
    print(f"[download] {QUIPUS_REPO} -> {dest} (~1.2GB) ...")
    snapshot_download(repo_id=QUIPUS_REPO, local_dir=str(dest),
                      ignore_patterns=["artifacts/*", ".git*"])
    print("[download] complete. Prefetching SNAC decoder ...")
    from snac import SNAC
    SNAC.from_pretrained(SNAC_REPO)
    print("[download] SNAC cached.")
    return 0


def load_teacher(args):
    model_dir = W(args, "quipus_model")
    if not model_dir.exists():
        sys.exit("missing quipus_model/ — run --stage download first")
    import torch
    from transformers import AutoModelForCausalLM, AutoTokenizer
    from snac import SNAC

    cuda = torch.cuda.is_available()
    dtype = torch.bfloat16 if cuda else torch.float32
    device = "cuda" if cuda else "cpu"
    print(f"[quipus] loading ({device}/{dtype}) ...")
    tok = AutoTokenizer.from_pretrained(str(model_dir), use_fast=False)
    model = AutoModelForCausalLM.from_pretrained(
        str(model_dir), dtype=dtype).to(device).eval()
    audio_end = tok.convert_tokens_to_ids("<audio_end>")
    snac = SNAC.from_pretrained(SNAC_REPO).eval().to(device)
    print(f"[quipus] ready (audio_end={audio_end})")
    return tok, model, snac, device, audio_end


def synth(tok, model, snac, device, audio_end, text, speaker="Sido",
          temperature=0.7, top_p=0.9, max_tokens=1024):
    import torch

    prompt = f"{speaker}: {text} <audio_start> "
    inputs = tok(prompt, return_tensors="pt").to(device)
    t0 = time.time()
    with torch.no_grad():
        out = model.generate(**inputs, max_new_tokens=max_tokens,
                             temperature=temperature, top_p=top_p,
                             do_sample=True, eos_token_id=[audio_end])
    dt = time.time() - t0
    toks = tok.convert_ids_to_tokens(out[0][inputs.input_ids.shape[1]:].tolist())
    parsed = []
    for t in toks:
        m = TOKEN_RE.fullmatch(t)
        if m:
            parsed.append((int(m.group(1)), int(m.group(2))))
    l0, l1, l2 = [], [], []
    i = 0
    while i + 7 <= len(parsed):
        window = parsed[i:i + 7]
        if [layer for layer, _ in window] == FRAME_LAYER_PATTERN:
            codes = [code for _, code in window]
            l0.append(codes[0])
            l1.extend([codes[1], codes[4]])
            l2.extend([codes[2], codes[3], codes[5], codes[6]])
            i += 7
        else:
            i += 1
    if not l0:
        return None, dt, 0
    with torch.no_grad():
        wav = snac.decode([
            torch.tensor([l0], dtype=torch.long, device=device),
            torch.tensor([l1], dtype=torch.long, device=device),
            torch.tensor([l2], dtype=torch.long, device=device),
        ])
    return wav.detach().squeeze().float().cpu().numpy(), dt, len(l0)


def stats(audio):
    import numpy as np

    a = np.asarray(audio, dtype=float)
    return len(a), len(a) / TEACHER_SR, float((a ** 2).mean() ** 0.5)


# --------------------------------------------------------------------------
# stage: validate
# --------------------------------------------------------------------------
def stage_validate(args) -> int:
    tok, model, snac, device, audio_end = load_teacher(args)
    import soundfile as sf

    runs = W(args, "runs")
    runs.mkdir(parents=True, exist_ok=True)
    failed = 0
    for name, ol in VALIDATE_CASES:
        audio, dt, frames = synth(tok, model, snac, device, audio_end,
                                  normalize(ol), speaker=args.speaker,
                                  temperature=args.temperature)
        if audio is None:
            print(f"[validate] FAIL {name}: no SNAC frames")
            failed += 1
            continue
        n, dur, rms = stats(audio)
        ok = n > 0.2 * TEACHER_SR and rms > 0.005
        failed += not ok
        p = runs / f"quipus_{args.speaker.lower()}_{name}.wav"
        sf.write(str(p), audio, TEACHER_SR)
        print(f"[validate] {'PASS' if ok else 'FAIL'} {name}: {dur:.2f}s, "
              f"wall {dt:.1f}s, rms {rms:.4f}, frames {frames} -> {p} "
              "<-- LISTEN")
    print(f"[validate] {'ALL PASS — proceed to bulk' if not failed else f'{failed} FAILED — STOP'}")
    return 1 if failed else 0


# --------------------------------------------------------------------------
# stage: bulk
# --------------------------------------------------------------------------
def stage_bulk(args) -> int:
    rows = load_transcripts()
    if args.limit:
        rows = rows[:args.limit]
    teacher = W(args, "teacher")
    out_wavs = teacher / "wavs_24k"
    out_wavs.mkdir(parents=True, exist_ok=True)
    manifest = teacher / "manifest.tsv"
    done = set()
    if manifest.exists():
        for line in manifest.read_text(encoding="utf-8").splitlines()[1:]:
            if line.strip():
                done.add(line.split("\t")[0])
    todo = [(u, t) for u, t in rows if u not in done]
    print(f"[bulk] {len(todo)} to synthesize ({len(done)} cached), "
          f"speaker={args.speaker}")
    if not todo:
        return 0
    tok, model, snac, device, audio_end = load_teacher(args)
    import soundfile as sf

    if not manifest.exists():
        manifest.write_text("utt_id\twav_path\ttext_olchiki\tspeaker\tdur_s\n",
                            encoding="utf-8")
    with open(manifest, "a", encoding="utf-8") as f:
        for n, (uid, ol) in enumerate(todo):
            audio, dt, frames = synth(tok, model, snac, device, audio_end,
                                      normalize(ol), speaker=args.speaker,
                                      temperature=args.temperature)
            if audio is None:
                print(f"[bulk] FAIL {uid}: no frames (retries next run)")
                continue
            dur = len(audio) / TEACHER_SR
            sf.write(str(out_wavs / f"{uid}.wav"), audio, TEACHER_SR)
            f.write(f"{uid}\twavs_24k/{uid}.wav\t{ol}\t{args.speaker}\t"
                    f"{dur:.2f}\n")
            f.flush()
            if (n + 1) % 25 == 0:
                print(f"[bulk] {n + 1}/{len(todo)} (last {uid}: {dur:.1f}s "
                      f"audio in {dt:.1f}s wall)")
    print(f"[bulk] manifest rows done. Re-run same command after timeouts.")
    return 0


# --------------------------------------------------------------------------
# stage: train (prep + Coqui VITS)
# --------------------------------------------------------------------------
def prep_student(args):
    import librosa
    import soundfile as sf

    teacher = W(args, "teacher")
    manifest = teacher / "manifest.tsv"
    if not manifest.exists():
        sys.exit("missing teacher/manifest.tsv — run --stage bulk first")
    have = {}
    for line in manifest.read_text(encoding="utf-8").splitlines()[1:]:
        if line.strip():
            p = line.split("\t")
            have[p[0]] = p[2]
    print(f"[prep] teacher utterances: {len(have)}")
    out_dir = teacher / "wavs"  # coqui formatter resolves <path>/wavs/<id>.wav
    out_dir.mkdir(parents=True, exist_ok=True)
    todo = [u for u in have if not (out_dir / f"{u}.wav").exists()]
    print(f"[prep] resampling {len(todo)} to {TRAIN_SR}Hz "
          f"(cached {len(have) - len(todo)}) ...")
    for n, uid in enumerate(todo):
        y, _ = librosa.load(str(teacher / "wavs_24k" / f"{uid}.wav"),
                            sr=TRAIN_SR, mono=True)
        sf.write(str(out_dir / f"{uid}.wav"), y, TRAIN_SR)
        if (n + 1) % 500 == 0:
            print(f"[prep] {n + 1}/{len(todo)}")
    splits = load_splits()
    texts = dict(load_transcripts())
    for split, csv in (("train", "coqui_train.csv"), ("dev", "coqui_dev.csv")):
        lines = []
        for uid in splits[split]:
            if uid in have and (out_dir / f"{uid}.wav").exists():
                t = texts[uid]
                assert "|" not in t
                lines.append(f"{uid}|{t}|{t}")
        (teacher / csv).write_text("\n".join(lines) + "\n", encoding="utf-8")
        print(f"[prep] {csv}: {len(lines)} rows (split {len(splits[split])})")
    chars: set[str] = set()
    for t in texts.values():
        chars.update(t)
    chars.discard(" ")
    charset = sorted(chars)
    bad = [c for c in charset
           if not ("\u1c50" <= c <= "\u1c7f" or c in "।.,?!:;'-()\"/—–")]
    assert not bad, f"non-OlChiki: {[hex(ord(c)) for c in bad]}"
    (teacher / "charset.json").write_text(
        json.dumps({"characters": charset}, indent=1, ensure_ascii=False)
        + "\n", encoding="utf-8")
    print(f"[prep] charset: {len(charset)} symbols")


def stage_train(args) -> int:
    prep_student(args)

    from trainer import Trainer, TrainerArgs

    from TTS.tts.configs.shared_configs import (BaseDatasetConfig,
                                                CharactersConfig)
    from TTS.tts.configs.vits_config import VitsConfig
    from TTS.tts.datasets import load_tts_samples
    from TTS.tts.models.vits import Vits, VitsAudioConfig
    from TTS.tts.utils.text.tokenizer import TTSTokenizer
    from TTS.utils.audio import AudioProcessor

    teacher = W(args, "teacher")
    charset = json.loads((teacher / "charset.json").read_text(
        encoding="utf-8"))["characters"]
    dataset_config = BaseDatasetConfig(
        formatter="ljspeech", meta_file_train="coqui_train.csv",
        meta_file_val="coqui_dev.csv", path=str(teacher), language="sat")
    run_dir = str(W(args, "runs", "vits_sat"))
    config = VitsConfig(
        model="vits_sat_sido", run_name="santali_vits_sido",
        project_name="vachak",
        run_description="Santali Ol-Chiki VITS distilled from Quipus Sido",
        dashboard_logger="tensorboard", logger_uri=run_dir,
        audio=VitsAudioConfig(sample_rate=TRAIN_SR, hop_length=256,
                              win_length=1024, fft_size=1024, mel_fmin=0,
                              mel_fmax=8000, num_mels=80),
        batch_size=args.batch, batch_group_size=0, eval_batch_size=8,
        num_loader_workers=4, num_eval_loader_workers=2,
        mixed_precision=True, epochs=args.epochs,
        text_cleaner="no_cleaners", use_phonemes=False, phonemizer=None,
        phoneme_language=None, compute_input_seq_cache=True,
        print_step=50, print_eval=True, save_step=2000, run_eval_steps=1000,
        save_n_checkpoints=5, save_checkpoints=True, save_all_best=True,
        target_loss="loss_0", save_best_after=10000,
        characters=CharactersConfig(characters="".join(charset),
                                    punctuations="", pad="<PAD>", eos="</s>",
                                    bos="<s>", blank="<BLNK>", is_unique=True,
                                    is_sorted=True),
        phoneme_cache_path=None, precompute_num_workers=4,
        start_by_longest=True,
        max_audio_len=int(12.5 * TRAIN_SR),  # coqui lengths are SAMPLES
        min_audio_len=int(1.5 * TRAIN_SR), max_text_len=400, min_text_len=1,
        test_sentences=[t for _, t in VALIDATE_CASES],
        use_speaker_embedding=False, use_d_vector_file=False)
    ap_audio = AudioProcessor.init_from_config(config)
    train_samples, eval_samples = load_tts_samples(
        dataset_config, eval_split=True)
    print(f"[data] train={len(train_samples)} eval={len(eval_samples)}")
    tokenizer, config = TTSTokenizer.init_from_config(config)
    model = Vits(config, ap_audio, tokenizer, speaker_manager=None)
    trainer = Trainer(TrainerArgs(restore_path=args.restore), config,
                      run_dir, model=model, train_samples=train_samples,
                      eval_samples=eval_samples)
    trainer.fit()
    return 0


# --------------------------------------------------------------------------
# stage: listen
# --------------------------------------------------------------------------
def listen_cases():
    splits = load_splits()
    texts = dict(load_transcripts())
    cases = list(VALIDATE_CASES)
    for uid in splits["eval"][:2]:
        cases.append((f"heldout-{uid}", texts[uid]))
    return cases


def pick_checkpoint(args) -> tuple[str, str]:
    import glob as _glob

    run = W(args, "runs", "vits_sat")
    if args.checkpoint:
        ckpt = args.checkpoint
    else:
        cands = [str(run / "best_model.pth")] + sorted(
            _glob.glob(str(run / "checkpoint_*.pth")))
        cands = [c for c in cands if Path(c).exists()]
        if not cands:
            sys.exit("no checkpoint — train first")
        ckpt = cands[0] if cands[0].endswith("best_model.pth") else cands[-1]
    cfg = str(Path(ckpt).parent / "config.json")
    if not Path(cfg).exists():
        sys.exit(f"config.json missing next to {ckpt}")
    return ckpt, cfg


def stage_listen(args) -> int:
    ckpt, cfg = pick_checkpoint(args)
    import soundfile as sf
    from TTS.utils.synthesizer import Synthesizer

    print(f"[listen] {ckpt}")
    synth = Synthesizer(tts_checkpoint=ckpt, tts_config_path=cfg,
                        use_cuda=args.cuda)
    sr = synth.output_sample_rate
    out = W(args, "listen")
    out.mkdir(parents=True, exist_ok=True)
    report = [f"checkpoint: {ckpt}", f"sample_rate: {sr}"]
    import numpy as np

    for name, text in listen_cases():
        wav = synth.tts(text, split_sentences=False)
        a = np.asarray(wav, dtype=float)
        dur, rms = len(a) / sr, float((a ** 2).mean() ** 0.5)
        sf.write(str(out / f"student_{name}.wav"), a, sr)
        ok = len(a) > 0.2 * sr and rms > 0.005
        line = (f"[listen] {'PASS' if ok else 'FAIL'} {name}: {dur:.2f}s, "
                f"rms {rms:.4f}")
        print(line)
        report.append(line)
    refs = sorted(W(args, "runs").glob("quipus_sido_*.wav"))
    report.append(f"sido_refs: {[r.name for r in refs]} (A/B by ear)")
    (out / "report.txt").write_text("\n".join(report) + "\n",
                                    encoding="utf-8")
    print("[listen] download listen/ + runs/quipus_sido_*.wav and LISTEN.")
    return 0


# --------------------------------------------------------------------------
# stage: export + verify
# --------------------------------------------------------------------------
def load_vits(ckpt: str):
    import torch
    from TTS.tts.configs.vits_config import VitsConfig
    from TTS.tts.models.vits import Vits
    from TTS.tts.utils.text.tokenizer import TTSTokenizer
    from TTS.utils.audio import AudioProcessor

    run_dir = Path(ckpt).parent
    config = VitsConfig()
    config.load_json(str(run_dir / "config.json"))
    ap = AudioProcessor.init_from_config(config)
    tokenizer, config = TTSTokenizer.init_from_config(config)
    model = Vits(config, ap, tokenizer, speaker_manager=None)
    state = torch.load(ckpt, map_location="cpu", weights_only=False)
    model.load_state_dict(state.get("model", state))
    model.eval()
    return model, tokenizer, config


def stage_export(args) -> int:
    import onnx

    ckpt, _ = pick_checkpoint(args) if not args.checkpoint \
        else (args.checkpoint, None)
    export = W(args, "export")
    export.mkdir(parents=True, exist_ok=True)
    model, tokenizer, config = load_vits(ckpt)
    tmp = export / "vits-sat-opset15.onnx"
    model.export_onnx(str(tmp), verbose=False)
    m = onnx.load(str(tmp))
    try:
        m = onnx.version_converter.convert_version(m, 17)
        print("[export] opset -> 17")
    except Exception as e:
        print(f"[export] opset convert skipped ({e})")
    chars = tokenizer.characters
    meta = {"sample_rate": "22050", "n_speakers": "1", "language": "sat",
            "comment": "coqui-santali-sido-distilled",
            "frontend": "characters", "bos_id": str(chars.bos_id),
            "eos_id": str(chars.eos_id), "blank_id": str(chars.blank_id),
            "pad_id": str(chars.pad_id),
            "add_blank": "1" if getattr(config, "add_blank", True) else "0",
            "use_eos_bos": "1", "voice": "santali-sido-distilled"}
    keys = {p.key for p in m.metadata_props}
    for k, v in meta.items():
        if k in keys:
            for p in m.metadata_props:
                if p.key == k:
                    p.value = v
        else:
            p = m.metadata_props.add()
            p.key, p.value = k, v
    out = export / "vits-sat.onnx"
    onnx.save(m, str(out))
    onnx.checker.check_model(str(out))
    print(f"[export] {out} ({out.stat().st_size / 1e6:.1f} MB, checker PASS)")
    inv = {v: k for k, v in chars.char_to_id.items()}
    vocab = [inv[i] for i in range(len(inv))]
    with open(export / "tokens.txt", "w", encoding="utf-8") as f:
        for i, ch in enumerate(vocab):
            f.write(f"{ch} {i}\n")
    print(f"[export] tokens.txt ({len(vocab)} symbols)")
    freq: dict[str, int] = {}
    for _, t in load_transcripts():
        for w in t.split():
            freq[w] = freq.get(w, 0) + 1
    top = sorted(freq, key=freq.get, reverse=True)[:200]
    with open(export / "lexicon.txt", "w", encoding="utf-8") as f:
        for w in top:
            f.write(f"{w}  {' '.join(c for c in w)}\n")
        for ch in vocab:
            if len(ch) == 1 and "\u1c50" <= ch <= "\u1c7f":
                f.write(f"{ch}  {ch}\n")
    print("[export] lexicon.txt done")
    return 0


def stage_verify(args) -> int:
    import sherpa_onnx

    export = W(args, "export")
    onnx_path = export / "vits-sat.onnx"
    assert onnx_path.exists(), "run --stage export first"
    v = sherpa_onnx.OfflineTtsVitsModelConfig(
        model=str(onnx_path), lexicon="",
        tokens=str(export / "tokens.txt"), data_dir="")
    mc = sherpa_onnx.OfflineTtsModelConfig(vits=v, num_threads=1,
                                           provider="cpu")
    tts = sherpa_onnx.OfflineTts(sherpa_onnx.OfflineTtsConfig(model=mc))
    lines = [f"export verify sr={tts.sample_rate}"]
    ok_all = True
    for text in ["ᱡᱚᱦᱟᱨ", "ᱟᱞᱮ ᱟᱥᱲᱟ ᱥᱮᱱᱚᱜ ᱠᱟᱱᱟ"]:
        audio = tts.generate(text, sid=0, speed=1.0)
        import numpy as np
        a = np.array(audio.samples)
        rms = float((a ** 2).mean() ** 0.5)
        ok = len(audio.samples) > 0.2 * tts.sample_rate and rms > 0.005
        ok_all &= ok
        lines.append(f"[verify] {'PASS' if ok else 'FAIL'} {text[:20]}: "
                     f"{len(audio.samples)} samples, rms {rms:.4f}")
    (export / "verify.log").write_text("\n".join(lines) + "\n",
                                       encoding="utf-8")
    print("\n".join(lines))
    return 0 if ok_all else 1


# --------------------------------------------------------------------------
def main() -> None:
    ap = argparse.ArgumentParser(description="Santali TTS all-in-one (Colab)")
    ap.add_argument("--stage", required=True,
                    choices=["setup", "download", "validate", "bulk",
                             "train", "listen", "export", "verify"])
    ap.add_argument("--workdir", default="/content/santali_tts")
    ap.add_argument("--speaker", default="Sido")
    ap.add_argument("--temperature", type=float, default=0.7)
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--epochs", type=int, default=300)
    ap.add_argument("--batch", type=int, default=16)
    ap.add_argument("--restore", default=None)
    ap.add_argument("--checkpoint", default=None)
    ap.add_argument("--cuda", action="store_true", default=True)
    args = ap.parse_args()
    Path(args.workdir).mkdir(parents=True, exist_ok=True)
    fn = {"setup": stage_setup, "download": stage_download,
          "validate": stage_validate, "bulk": stage_bulk,
          "train": stage_train, "listen": stage_listen,
          "export": stage_export, "verify": stage_verify}[args.stage]
    sys.exit(fn(args))


if __name__ == "__main__":
    main()
